$_MODULE['<{gmerchantcenterpro}prestashop>feed-settings_257243366cdf6a8ab66bfe17e6a2e28f'] = 'Devo attivare questa opzione?';
$_MODULE['<{gmerchantcenterpro}prestashop>feed-settings_70049bd7ee668b922ec899c297bf4731'] = 'Includere l\'ID attributo nell\'URL della combinazione?';
$_MODULE['<{gmerchantcenterpro}prestashop>feed-settings_089da1393bce22764af69480484e749c'] = 'Come impostare questa opzione?';
$_MODULE['<{gmerchantcenterpro}prestashop>feed-settings_1d0f4142cadcbf3c879df12a1585802a'] = 'Il \"feed id\" di un prodotto è costruito in questo modo: \"Prefisso negozio + lingua + id prodotto + separatore + id combinazione\". Ad esempio, il feed id BMFR17v32 corrisponde alla combinazione dell\'id 32 del prodotto dell\'id 17 del feed francese del negozio BM. Qui potete scegliere il separatore tra product id e combination id. Per impostazione predefinita il separatore è \"v\".';
$_MODULE['<{gmerchantcenterpro}prestashop>feed-settings_02dbf9e0c6202778497a4fef87c63ac7'] = 'Scegliere il separatore tra id prodotto e id combinazione';
$_MODULE['<{gmerchantcenterpro}prestashop>feed-settings_4e04157784f1bc3cbfe8581c66bff97e'] = 'Nota: sembra che abbiate escluso alcuni prodotti. Tenete quindi presente che, se modificate l\'opzione qui sopra, dovrete reimpostare l\'elenco dei prodotti da escludere. Per farlo andate nella scheda precedente \"Regole di esclusione dei prodotti\" per eliminare la lista, salvate la pagina e iniziate da capo la procedura. Di fatto se desiderate esportare ogni versione come prodotto a sé stante, le esclusioni sono da fare per versione e non per prodotto.';
$_MODULE['<{gmerchantcenterpro}prestashop>feed-settings_510ceacc1201b20210f0edb3601ccbf2'] = 'Che tipo di descrizione volete adottare?';
$_MODULE['<{gmerchantcenterpro}prestashop>feed-settings_ca0aa01b14c4daab61c2c3ee5067c257'] = 'FAQ sulla descrizione dei prodotti';
$_MODULE['<{gmerchantcenterpro}prestashop>feed-settings_a74a600016a3d3ea7e2866505211a5f4'] = 'A proposito della disponibilità dei prodotti';
$_MODULE['<{gmerchantcenterpro}prestashop>feed-settings_3d5b2d9c80034fffdda0e16b0aa2490b'] = 'Indicare i prodotti come disponibili SOLO se sono effettivamente in stock';
$_MODULE['<{gmerchantcenterpro}prestashop>feed-settings_a4db92556a5b3c6e9a18c203990d606e'] = 'Indicare sempre che i prodotti sono disponibili, ANCHE SE non sono in stock';
$_MODULE['<{gmerchantcenterpro}prestashop>feed-settings_5c0cd3b0d08c878903362281e57e8f8a'] = 'Se alcuni dei vostri prodotti hanno sia un codice EAN13/JAN che un codice UPC, potete dire al modulo quale dei due ha la priorità. Ad esempio: se il vostro negozio utilizza principalmente i codici EAN13/JAN e i codici UPC solo per alcuni prodotti, vorrete probabilmente che il modulo verifichi prima se è presente un codice EAN13/JAN e, in caso di riscontro positivo, lo usi. Se il valore non è disponibile il modulo controllerà il valore del codice UPC e, se presente, lo userà.';
$_MODULE['<{gmerchantcenterpro}prestashop>feed-settings_ba9d0100eea23aef66a998c2812716e7'] = 'Determinazione del GTIN prioritario (EAN13/JAN o UPC):';
