$_MODULE['<{gmerchantcenterpro}prestashop>module-tools_class_c994f5c074871357742776779a7c6041'] = 'Il tag \"CATEGORIA PRODOTTO GOOGLE\" => Devi associare ogni categoria predefinita di prodotto a una categoria ufficiale di Google';
$_MODULE['<{gmerchantcenterpro}prestashop>module-tools_class_199898875215dc70a275c0d08f093180'] = 'Il tag \"CATEGORIA\" => A differenza del tag \"Categoria prodotto Google\", il tag \"Categoria\" contiene le informazioni sulla categoria del prodotto secondo la propria classificazione';
$_MODULE['<{gmerchantcenterpro}prestashop>module-tools_class_30945a1160cfef2e6810bad0642a7f39'] = 'Il tag \"LINK\" => Questo è il link dell\'articolo';
$_MODULE['<{gmerchantcenterpro}prestashop>module-tools_class_6810b70e5cc04b03c7a722703ba1a25c'] = 'Il tag \"LINK IMMAGINE\" => Questo è l\'URL dell\'immagine principale del prodotto';
$_MODULE['<{gmerchantcenterpro}prestashop>module-tools_class_88e22f6108456494e9ff22cc7d522c77'] = 'Il tag \"CONDIZIONE\" => Questa è la condizione dell\'articolo. Ci sono solo 3 valori accettati: \"nuovo\", \"ricondizionato\" e \"usato\"';
$_MODULE['<{gmerchantcenterpro}prestashop>module-tools_class_a6aa6ebcc5dc7d0f145df19c202ed562'] = 'Il tag \"DISPONIBILITÁ\" => Questo indica la disponibilità dell\'articolo. Ci sono solo 3 valori accettati: \"disponibile\", \"non disponibile\" e \"pre-ordine\"';
$_MODULE['<{gmerchantcenterpro}prestashop>module-tools_class_16bbe64f420f506f1c1fa1af3a02a654'] = 'Il tag \"PREZZO\" => Questo è il prezzo dell\'articolo';
$_MODULE['<{gmerchantcenterpro}prestashop>module-tools_class_d89fefbc6021ac272d4cf263c4efb0e6'] = 'Il tag \"GTIN\" =>  Il \"Global Trade Item Number\" è uno degli codici identificativi di prodotto';
$_MODULE['<{gmerchantcenterpro}prestashop>module-tools_class_d1631df5c65d2d968bf89c18253923ef'] = 'Il tag \"MARCA\" => La marca del prodotto è uno degli codici identificativi di prodotto';
$_MODULE['<{gmerchantcenterpro}prestashop>module-tools_class_faf773fc15ef8b16d055f4d9f4b352ad'] = 'Il tag \"MPN\" => Il \"Manufacturer Part Number\" è uno degli codici identificativi di prodotto';
$_MODULE['<{gmerchantcenterpro}prestashop>module-tools_class_5d62534879deeba7dcd2408d27023eae'] = 'Il tag \"PER ADULTI\" => Questo tag indica che l\'articolo è solo per adulti';
$_MODULE['<{gmerchantcenterpro}prestashop>module-tools_class_e05668c1c9f4d44c28508d886219a7ca'] = 'Il tag \"SESSO\" => Questo tag consente di specificare il sesso per il quale il prodotto è stato progettato. Potete scegliere tra 3 valori predefiniti: \"maschile\", \"femminile\" o \"unisex\"';
$_MODULE['<{gmerchantcenterpro}prestashop>module-tools_class_1bfd5e5854d1ac1439d0c1fba2ed8a38'] = 'Il tag \"ETÀ\" => Questo tag consente di specificare la fascia d\'età per la quale il prodotto è stato progettato. Potete scegliere tra 5 valori predefiniti: \"adulti\", \"bambini\", \"1-5 anni\", \"3-12 mesi\" o \"neonato\"';
$_MODULE['<{gmerchantcenterpro}prestashop>module-tools_class_230ea3479ccabdfe236c4d65cab2f980'] = 'Il tag \"COLORE\" => Questo definisce il colore o i colori dominanti di un articolo';
$_MODULE['<{gmerchantcenterpro}prestashop>module-tools_class_5d553aefd82d6a33ded4e79e6c247ef1'] = 'Il tag \"TAGLIA\" => Indica la taglia di un articolo';
$_MODULE['<{gmerchantcenterpro}prestashop>module-tools_class_01351d720a98edee7bdf936ae2a4e618'] = 'Il tag \"TIPO DI TAGLIA\" => Questo tag permette di dare un\'informazione aggiuntiva sulla taglia dell\'abbigliamento. È possibile scegliere tra 4 valori predefiniti: \"regolare\", \"taglia piccola\", \"oversize\" o \"premaman\"';
